# Generated by .github/homebrew-formula.sh in sparewall/sparewall for each
# release; edits here are overwritten.
class Sparewall < Formula
  desc "CLI for Sparewall, an image-based Linux firewall"
  homepage "https://sparewall.org"
  version "0.3.3"
  license "GPL-3.0-only"

  on_macos do
    on_arm do
      url "https://github.com/sparewall/sparewall/releases/download/v0.3.3/sparewall-0.3.3-aarch64-darwin.tar.gz"
      sha256 "d7b8d9f04ed623c4c98dcf554c7d0e3962cac4b4788baabbdeb3970596dadc39"
    end
    on_intel do
      url "https://github.com/sparewall/sparewall/releases/download/v0.3.3/sparewall-0.3.3-x86_64-darwin.tar.gz"
      sha256 "b27e96c2c3ee4f8285757bb1b5ed51a3f53664b00317f78ae6e5665a4ca48821"
    end
  end

  on_linux do
    on_intel do
      url "https://github.com/sparewall/sparewall/releases/download/v0.3.3/sparewall-0.3.3-x86_64-linux.tar.gz"
      sha256 "0edf5fc2c84948e409415e9b9442536e5d11df0031f71ea0c24e770f0095303e"
    end
    on_arm do
      url "https://github.com/sparewall/sparewall/releases/download/v0.3.3/sparewall-0.3.3-aarch64-linux.tar.gz"
      sha256 "bf9070eef71c916122d9922bc2514ffc5777d8682c968b7dd721dfa607b467db"
    end
  end

  def install
    bin.install "sparewall"
    generate_completions_from_executable(bin/"sparewall", "completion")
  end

  # The macOS build is signed ad hoc, not notarized: should the download
  # carry the quarantine attribute, macOS would refuse to run it. Homebrew
  # installs the binary read-only, and removing an attribute needs write
  # permission, so it is lent and taken back. xattr fails when there is no
  # attribute to remove, which is the usual case.
  post_install_steps do
    on_macos do
      set_permissions "sparewall", "u+w", base: :bin, recursive: false
      run "/usr/bin/xattr", args: ["-d", "com.apple.quarantine", "{{bin}}/sparewall"],
          must_succeed: false, print_stderr: false, writable_paths: ["sparewall"], writable_base: :bin
      set_permissions "sparewall", "u-w", base: :bin, recursive: false
    end
  end

  test do
    assert_equal "sparewall #{version}", shell_output("#{bin}/sparewall --version").strip
  end
end
